{
  "summary": "Lock waits appear as `Lock` wait events in pg_stat_activity, while table bloat shows as `IO` waits everywhere indicating storage latency.",
  "likely_cause": "Distinguish by checking wait_event_type: Lock waits point to row/table locks; IO waits suggest table bloat or storage issues.",
  "confidence": "medium",
  "claims": [
    {
      "text": "Lock waits are identified by `Lock` wait events in pg_stat_activity.",
      "evidence_ids": ["RB-015#3"],
      "quote": "`Lock`, many rows blocked by the same pid."
    },
    {
      "text": "Incidents showed lock waits on the reservations table.",
      "evidence_ids": ["INC-0049#0"],
      "quote": "The sessions showed lock waits on the `reservations` table."
    },
    {
      "text": "Table bloat manifests as `IO` waits everywhere with storage latency.",
      "evidence_ids": ["RB-015#4"],
      "quote": "`IO` waits everywhere. Storage latency on the VM."
    },
    {
      "text": "`IO` waits everywhere are listed as a symptom of storage latency, not lock contention.",
      "evidence_ids": ["RB-015#3"],
      "quote": "`IO` waits everywhere. Storage latency on the VM."
    }
  ],
  "next_checks": [
    "Run SELECT pid, wait_event_type, wait_event FROM pg_stat_activity WHERE datname='inventory-db-01' AND wait_event_type IS NOT NULL;",
    "If wait_event_type = 'Lock', investigate blocking pid and transaction.",
    "If wait_event_type = 'IO', check storage latency metrics and run pgstattuple to assess table bloat.",
    "Compare recent autovacuum and analyze stats for tables with high bloat indicators."
  ]
}
